mapper.select:
SELECT next_sequence FROM nw_chat_session_outbox_sequences
WHERE tenant_id = #{tenantId} AND session_id = #{sessionId}
FOR UPDATE

SELECT projection_source_sequence AS "sourceSequence", projection_source_event_id AS "sourceEventId",
       projection_policy_version AS "policyVersion", projection_error_code AS "errorCode"
FROM nw_chat_session_outbox_sequences WHERE tenant_id=#{tenantId} AND session_id=#{sessionId}

mapper.update:
UPDATE nw_chat_session_outbox_sequences
SET projection_source_sequence=#{source.sequence}, projection_source_event_id=#{source.eventId},
    projection_policy_version=#{source.policyVersion}, projection_error_code=#{errorCode}, updated_at=now()
WHERE tenant_id=#{tenantId} AND session_id=#{sessionId}
  AND (projection_source_sequence IS NULL OR projection_source_sequence < #{source.sequence}
       OR (projection_source_sequence=#{source.sequence}
           AND (projection_source_event_id IS DISTINCT FROM #{source.eventId}
                OR projection_policy_version IS DISTINCT FROM #{source.policyVersion})))
